CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS bapc_security_core;
CREATE TABLE bapc_security_core.devices(device_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hostname text NOT NULL,hardware_uuid text UNIQUE NOT NULL,platform text NOT NULL,os_version text NOT NULL,attestation_public_key text,is_compromised boolean NOT NULL DEFAULT false,is_revoked boolean NOT NULL DEFAULT false,posture jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bapc_security_core.mesh_nodes(node_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),device_id uuid NOT NULL REFERENCES bapc_security_core.devices(device_id) ON DELETE CASCADE,public_key varchar(64) UNIQUE NOT NULL,internal_ipv4 inet UNIQUE NOT NULL,internal_ipv6 inet UNIQUE NOT NULL,listen_port integer NOT NULL DEFAULT 51820,node_type text NOT NULL,zone_assignment text NOT NULL,is_active boolean NOT NULL DEFAULT true,last_handshake timestamptz);
CREATE TABLE bapc_security_core.network_policies(policy_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,document jsonb NOT NULL,version integer NOT NULL DEFAULT 1,priority integer NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bapc_security_core.jit_grants(grant_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,target_resource text NOT NULL,target_zone text NOT NULL,justification text NOT NULL,approved_by uuid,granted_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,is_terminated boolean NOT NULL DEFAULT false,termination_reason text);
CREATE TABLE bapc_security_core.security_events(event_id uuid NOT NULL DEFAULT gen_random_uuid(),node_id uuid,event_timestamp timestamptz NOT NULL DEFAULT now(),severity text NOT NULL,engine_source text NOT NULL,event_type text NOT NULL,description text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(event_id,event_timestamp)) PARTITION BY RANGE(event_timestamp);
CREATE TABLE bapc_security_core.audit_chain(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,event_timestamp timestamptz NOT NULL DEFAULT now(),actor text NOT NULL,action text NOT NULL,subject text NOT NULL,payload jsonb NOT NULL,previous_hash char(64) NOT NULL,event_hash char(64) UNIQUE NOT NULL);
CREATE INDEX jit_active_idx ON bapc_security_core.jit_grants(user_id,target_zone,expires_at) WHERE is_terminated=false;
CREATE INDEX nodes_zone_idx ON bapc_security_core.mesh_nodes(zone_assignment) WHERE is_active=true;
